private string GetSearchStudentCode()
{
    if (IsStudentLogin())
        return GetLoggedStudentCode();

    return txtStudentCode.Text.Trim();
}

private void ExportWord(bool isView)
{
    if (User == null)
    {
        MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
        return;
    }

    string strStudentCode = GetSearchStudentCode();
    if (strStudentCode == "")
    {
        MsgBox.ShowWarning("Vui lòng nhập mã học viên!");
        txtStudentCode.Focus();
        return;
    }

    SIM_Branch obj = new SIM_Branch();
    DataTable dtbData = obj.GetDataTable("Sim_student_searchinfo_print", "@StudentCode", strStudentCode);

    if (dtbData == null)
    {
        MsgBox.ShowError("Việc tải thông tin bị lỗi!");
        return;
    }

    if (dtbData.Rows.Count == 0)
    {
        MsgBox.ShowWarning(String.Format("Không tìm thấy học viên với mã \"{0}\".", strStudentCode));
        return;
    }

    DataRow drw = dtbData.Rows[0];

    string strPath = System.Web.HttpContext.Current.Server.MapPath("~");
    string strFileNameAs = "Thong tin hoc vien " + strStudentCode + ".doc";
    string strFilePath = strPath + "\\Template\\Report\\Thong tin hoc vien 1.docx";
    string strExportDir = strPath + "\\Export\\Report\\";
    string strFilePathAs = strExportDir + strFileNameAs;

    if (!File.Exists(strFilePath))
    {
        MsgBox.ShowError("Không tìm thấy file mẫu Word!");
        return;
    }

    if (!Directory.Exists(strExportDir))
        Directory.CreateDirectory(strExportDir);

    try
    {
        Aspose.Words.LoadOptions options = new Aspose.Words.LoadOptions();
        options.LoadFormat = Aspose.Words.LoadFormat.Docx;

        Aspose.Words.Document document = new Aspose.Words.Document(strFilePath, options);

        document.MailMerge.Execute(new[] { "FullName" }, new[] { GetText(drw["FullName"]) });
        document.MailMerge.Execute(new[] { "StudentCode" }, new[] { GetText(drw["Studentcode"]) });
        document.MailMerge.Execute(new[] { "BirthDateText" }, new[] { GetText(drw["Birthdatetext"]) });
        document.MailMerge.Execute(new[] { "ClassName" }, new[] { GetText(drw["Classname"]) });
        document.MailMerge.Execute(new[] { "CourseId" }, new[] { GetText(drw["Courseid"]) });
        document.MailMerge.Execute(new[] { "PersonId" }, new[] { GetText(drw["Personid"]) });
        document.MailMerge.Execute(new[] { "PersonIdDate" }, new[] { FormatDate(drw["Persioniddate"]) });
        document.MailMerge.Execute(new[] { "PersonIdPlace" }, new[] { GetText(drw["Persionidplace"]) });
        document.MailMerge.Execute(new[] { "DriverCerNo" }, new[] { GetText(drw["DriverCerNo"]) });
        document.MailMerge.Execute(new[] { "DriverCerDate" }, new[] { FormatDate(drw["DriverCerDate"]) });
        document.MailMerge.Execute(new[] { "DriverCerPlace" }, new[] { GetText(drw["DriverCerPlace"]) });

        document.Save(strFilePathAs, Aspose.Words.SaveFormat.Doc);

        if (isView)
            OpenNewTab(DCore.Globals.ApplicationVRoot + "/viewer.html?filetype=doc&key=" + ViewFile.GenerateKeyForExport(strFilePathAs, strFileNameAs, User.UserName, "Viet$cong"));
        else
            Response.Redirect(DCore.Globals.ApplicationVRoot + "/DownloadFile.ashx?key=" + DownloadFile.GenerateKeyForExport(strFilePathAs, strFileNameAs, User.UserName, "Viet$minh"));
    }
    catch (Exception)
    {
        MsgBox.ShowError("Việc xuất mẫu Word bị lỗi!");
    }
}

